!(function () {
    "use strict";
    var n = tinymce.util.Tools.resolve("tinymce.PluginManager"),
        t = function (n) {
            n.addCommand("InsertReadMore", function () {
				var text = n.selection.getContent({
                'format': 'html'
				});
				if (text && text.length > 0) {
					n.execCommand("mceInsertContent", false, '<div class="read-more"><div class="read-more-remove" style="display:none">X</div><div class=read-more-content>' + text + '</div><button class="read-more-button" type="button" style="display:none"><span class="read-more-title">&nbsp;</span></button></div>');
				}
            });
        },
        o = function (n) {
            n.addButton(
				"readmore", { 
					text: 'Read More',
					icon: false,
					tooltip: "Read More", 
					cmd: "InsertReadMore" 
				}
			), 
			n.addMenuItem(
				"readmore", { 
					icon: "false", 
					text: "Read More'", 
					cmd: "InsertReadMore", 
					context: "insert" 
				}
			);
        };
    n.add("readmore", function (n) {
        t(n), o(n);
    });
})();
